export default async function run(ctx) {
  const set = createRegExpSet();
  init(set);
  // The original's Run() returned "Found" or "NotFound" (scriptResult) to a calling script.
  return searchRegExpSet(ctx, set, { image: '~~~', decodeShy: true });
}
